 77→    headers: { "content-type": "application/json", "x-tdai-service-id": SERVICE_ID, authorization: `Bearer [REDACTED] "x-tdai-user-key": key, ...extraHeaders },
 78→    body: JSON.stringify(body),
 79→  });
 80→  return res.json().catch(() => ({ code: -1, message: `non-JSON (${res.status})` }));
