 89→/**
 90→ * @param input  任务目录路径,或 { tokens, pair }
 91→ * @param opts   { read, keyFile, team_id, author_agent_id, author_user_id }
 92→ * @returns { [asset_id]: { mode, version, content_hash, tokens:[明文], token_sha256, adoption_fields,
 93→ *                          verified, read_purpose, why } }
 94→ */
 95→export async function resolveTokens(input, opts = {}) {
 96→  let tokens, pair;
 97→  if (typeof input === "string") {
 98→    const taskDir = resolve(REPO, input);
 99→    tokens = existsSync(join(taskDir, "tokens.json")) ? JSON.parse(readFileSync(join(taskDir, "tokens.json"), "utf8")) : {};
100→    pair = existsSync(join(taskDir, "pair.json")) ? JSON.parse(readFileSync(join(taskDir, "pair.json"), "utf8")) : {};
101→  } else {
102→    tokens = input?.tokens ?? {};
103→    pair = input?.pair ?? {};
104→  }
105→  const ids = Object.keys(tokens).filter((k) => !k.startsWith("_"));
106→  const team_id = opts.team_id ?? pair.team_id;
107→  const author_agent_id = opts.author_agent_id ?? pair.author_agent_id;
108→
109→  let key = null, read = opts.read ?? null, author_user_id = opts.author_user_id ?? null;
110→  const ensureReader = async () => {
111→    if (read) return;
112→    key = keyFrom(opts.keyFile ?? "deploy/global-images/.topic4-user-key");
113→    read = coreReader(key);
114→  };
115→  const ensureAuthorUser = async () => {
116→    if (author_user_id || !author_agent_id) return;
117→    if (!key) key = keyFrom(opts.keyFile ?? "deploy/global-images/.topic4-user-key");
118→    const ag = await corePost("/v3/meta/agent/get", { agent_id: author_agent_id }, key);
119→    author_user_id = ag?.data?.owner_user_id ?? null;
120→  };
121→
122→  const out = {};
123→  for (const id of ids) {
124→    const spec = tokens[id] ?? {};
125→    const base = { adoption_fields: spec.adoption_fields ?? null, read_purpose: "manage" };
126→
127→    // 明文形态(老批次):原样通过,不联网。
128→    if (Array.isArray(spec.tokens) && spec.tokens.length) {
129→      out[id] = { ...base, mode: "plain", version: spec.version ?? null, content_hash: spec.content_hash ?? null,
130→        tokens: spec.tokens, token_sha256: spec.tokens.map(sha256Hex), verified: true, read_purpose: null };
131→      continue;
132→    }
133→    if (!Array.isArray(spec.token_sha256) || !spec.token_sha256.length) {
134→      out[id] = { ...base, mode: "none", version: spec.version ?? null, content_hash: null, tokens: [], token_sha256: [], verified: false, why: "既无明文也无 token_sha256" };
135→      continue;
136→    }
137→    // 哈希形态:四元组必须齐,缺一个就不算钉住。
138→    const pinVersion = spec.version ?? null, pinHash = spec.content_hash ? String(spec.content_hash).toLowerCase() : null;
139→    if (pinVersion == null || !pinHash) {
140→      out[id] = { ...base, mode: "hash", version: pinVersion, content_hash: pinHash, tokens: [], token_sha256: spec.token_sha256, verified: false,
141→        why: "tokens.json 没有钉住 version/content_hash,无法确认 Core 里读到的是冻结的那一版" };
142→      continue;
143→    }
144→    // 离线路线:显式要求,或没有读取器且密钥文件不存在(干净克隆)。有密钥时不走这里。
145→    const keyPath = resolve(REPO, opts.keyFile ?? "deploy/global-images/.topic4-user-key");
146→    const keyMissing = !read && !existsSync(keyPath);
147→    const offline = opts.offline === true || process.env.TOKENS_OFFLINE === "1" || keyMissing;
148→    if (offline) { out[id] = resolveBurned(id, spec, loadBurned(opts.burnedFile), { keyMissing }); continue; }
149→    await ensureReader(); await ensureAuthorUser();
150→    let r;
151→    try { r = await read({ team_id, user_id: author_user_id, agent_id: author_agent_id, skill_id: id, version: pinVersion }); }
152→    catch (e) { r = { code: -1, message: e.message }; }
153→    if (r?.code !== 0) {
154→      out[id] = { ...base, mode: "hash", version: pinVersion, content_hash: pinHash, tokens: [], token_sha256: spec.token_sha256, verified: false,
155→        why: `Core 管理读取失败(${r?.message ?? r?.code})——读不到 ≠ 没有` };
156→      continue;
157→    }
158→    const content = r.data?.content ?? "";
159→    const gotVersion = r.data?.version ?? null;
160→    if (gotVersion !== pinVersion) {
161→      out[id] = { ...base, mode: "hash", version: pinVersion, content_hash: pinHash, tokens: [], token_sha256: spec.token_sha256, verified: false,
162→        why: `Core 返回版本 ${gotVersion},钉住的是版本 ${pinVersion}` };
163→      continue;
164→    }
165→    const gotHash = md5Hex(content);
166→    if (gotHash !== pinHash) {
167→      out[id] = { ...base, mode: "hash", version: pinVersion, content_hash: pinHash, tokens: [], token_sha256: spec.token_sha256, verified: false,
168→        why: `正文 md5 ${gotHash.slice(0, 12)} ≠ 钉住的 content_hash ${pinHash.slice(0, 12)}` };
169→      continue;
170→    }
171→    const pat = spec.token_pattern ? new RegExp(spec.token_pattern, "g") : null;
172→    const found = [];
173→    if (pat) { let m; while ((m = pat.exec(content))) found.push(m[1] ?? m[0]); }
174→    const plaintext = [...new Set(found)];
175→    const want = spec.token_sha256.map((h) => String(h).toLowerCase());
176→    const got = plaintext.map(sha256Hex);
177→    const ok = plaintext.length > 0 && want.every((h) => got.includes(h)) && got.every((h) => want.includes(h));
178→    out[id] = { ...base, mode: "hash", version: pinVersion, content_hash: pinHash, tokens: ok ? plaintext : [], token_sha256: spec.token_sha256, verified: ok,
179→      why: ok ? "版本、内容哈希、token 哈希与冻结一致" : `正文抽出 ${plaintext.length} 个值,sha256 与 token_sha256 不一致` };
180→  }
181→  return out;
182→}
