184→/**
185→ * 明文形态(给 judge-hard / judge-outcome / delivery-audit / adoption 用),**带版本**。
186→ * 任何一个资产未 verified 就抛:分析不能在读错版本、读错内容、读不到的情况下继续。
187→ */
188→export function plainTokensOrThrow(resolved) {
189→  const bad = Object.entries(resolved ?? {}).filter(([, r]) => r.verified !== true);
190→  if (bad.length) {
191→    throw new Error(`判别值未能按冻结四元组解析,分析中止:${bad.map(([id, r]) => `${id}(${r.why ?? "unverified"})`).join("; ")}`);
192→  }
193→  const out = {};
194→  for (const [id, r] of Object.entries(resolved)) {
195→    out[id] = { version: r.version ?? null, content_hash: r.content_hash ?? null, tokens: r.tokens, ...(r.adoption_fields ? { adoption_fields: r.adoption_fields } : {}) };
196→  }
197→  return out;
198→}
