203→  const taskDir = opt("task") ?? args.find((a) => !a.startsWith("--")) ?? "evaluation/tasks/bridge-addr";
204→  const resolved = await resolveTokens(taskDir, { keyFile: opt("key"), offline: args.includes("--offline") });
205→  let bad = 0;
206→  for (const [id, r] of Object.entries(resolved)) {
207→    if (!r.verified) bad += 1;
208→    console.log(`${r.verified ? "OK  " : "BAD "} ${id}  mode=${r.mode}  version=${r.version ?? "?"}  plaintext=${r.tokens.length}  ${r.why ?? ""}`);
209→  }
210→  const out = opt("out");
211→  if (out) {
212→    if (bad) { console.error(`\n${bad} 个资产未 verified,不写明文文件`); process.exit(1); }
213→    writeFileSync(out, JSON.stringify(plainTokensOrThrow(resolved), null, 2) + "\n");
214→    console.log(`\nplaintext form → ${out}(用完即删,不得进仓库)`);
215→  }
216→  console.log(bad ? `\n${bad} 个资产未能按冻结四元组解析` : "\n全部按冻结四元组解析并校验");
217→  process.exit(bad ? 1 : 0);
218→}
