 89→/**
 90→ * @param input  任务目录路径,或 { tokens, pair }
 91→ * @param opts   { read, keyFile, team_id, author_agent_id, author_user_id }
 92→ * @returns { [asset_id]: { mode, version, content_hash, tokens:[明文], token_sha256, adoption_fields,
 93→ *                          verified, read_purpose, why } }
 94→ */
 95→export async function resolveTokens(input, opts = {}) {
 96→  let tokens, pair;
 97→  if (typeof input === "string") {
 98→    const taskDir = resolve(REPO, input);
 99→    tokens = existsSync(join(taskDir, "tokens.json")) ? JSON.parse(readFileSync(join(taskDir, "tokens.json"), "utf8")) : {};
100→    pair = existsSync(join(taskDir, "pair.json")) ? JSON.parse(readFileSync(join(taskDir, "pair.json"), "utf8")) : {};
101→  } else {
102→    tokens = input?.tokens ?? {};
103→    pair = input?.pair ?? {};
104→  }
105→  const ids = Object.keys(tokens).filter((k) => !k.startsWith("_"));
106→  const team_id = opts.team_id ?? pair.team_id;
107→  const author_agent_id = opts.author_agent_id ?? pair.author_agent_id;
108→
109→  let key = null, read = opts.read ?? null, author_user_id = opts.author_user_id ?? null;
110→  const ensureReader = async () => {
111→    if (read) return;
112→    key = keyFrom(opts.keyFile ?? "deploy/global-images/.topic4-user-key");
113→    read = coreReader(key);
114→  };
115→  const ensureAuthorUser = async () => {
116→    if (author_user_id || !author_agent_id) return;
117→    if (!key) key = keyFrom(opts.keyFile ?? "deploy/global-images/.topic4-user-key");
118→    const ag = await corePost("/v3/meta/agent/get", { agent_id: author_agent_id }, key);
119→    author_user_id = ag?.data?.owner_user_id ?? null;
120→  };
121→
122→  const out = {};
123→  for (const id of ids) {
124→    const spec = tokens[id] ?? {};
125→    const base = { adoption_fields: spec.adoption_fields ?? null, read_purpose: "manage" };
126→
127→    // 明文形态(老批次):原样通过,不联网。
128→    if (Array.isArray(spec.tokens) && spec.tokens.length) {
129→      out[id] = { ...base, mode: "plain", version: spec.version ?? null, content_hash: spec.content_hash ?? null,
130→        tokens: spec.tokens, token_sha256: spec.tokens.map(sha256Hex), verified: true, read_purpose: null };
131→      continue;
